import re

def compare_versions(a: str, b: str) -> int:
    """
    Compares two Semantic Versioning 2.0.0 strings and returns:
    -1 if a < b
    0 if a == b
    1 if a > b

    Build metadata is ignored in precedence rules.
    """
    def parse_version(version_str: str):
        # Split build metadata first as it is ignored
        main_part = version_str.split('+')[0]
        # Split pre-release part
        if '-' in main_part:
            main_part, pre_release = main_part.split('-', 1)
        else:
            pre_release = None

        # Parse core components
        core_parts = [int(x) for x in main_part.split('.')]

        # Parse pre-release identifiers
        pre_parts = []
        if pre_release:
            for part in pre_release.split('.'):
                if part.isdigit():
                    pre_parts.append(int(part))
                else:
                    pre_parts.append(part)

        return core_parts, pre_parts

    try:
        core_a, pre_a = parse_version(a)
        core_b, pre_b = parse_version(b)
    except (ValueError, IndexError):
        # In a production environment, you might raise a custom exception 
        # for invalid SemVer strings.
        raise ValueError("Invalid Semantic Versioning string.")

    # 1. Compare Core (Major, Minor, Patch)
    if core_a < core_b:
        return -1
    if core_a > core_b:
        return 1

    # 2. Compare Pre-release presence
    # A version with a pre-release has lower precedence than one without.
    if pre_a is None and pre_b is not None:
        return 1
    if pre_a is not None and pre_b is None:
        return -1
    if pre_a is None and pre_b is None:
        return 0

    # 3. Compare Pre-release identifiers
    # If both have pre-releases, compare them dot by dot
    for part_a, part_b in zip(pre_a, pre_b):
        type_a = type(part_a)
        type_b = type(part_b)

        if type_a == type_b:
            if part_a < part_b:
                return -1
            if part_a > part_b:
                return 1
        else:
            # Numeric identifiers have lower precedence than non-numeric
            if type_a == int:
                return -1
            else:
                return 1

    # 4. Shorter set of identifiers is lower precedence if all preceding are equal
    if len(pre_a) < len(pre_b):
        return -1
    if len(pre_a) > len(pre_b):
        return 1

    return 0
