def number_to_words(n: int) -> str:
    """
    Converts an integer to its English word representation.

    Args:
        n (int): An integer between 0 and 999,999,999,999 inclusive.

    Returns:
        str: The English words for the integer.

    Raises:
        ValueError: If n is outside the valid range.
    """
    if not isinstance(n, int) or n < 0 or n > 999_999_999_999:
        raise ValueError("Input must be an integer between 0 and 999,999,999,999.")

    if n == 0:
        return "zero"

    units = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    teens = ["ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"]
    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
    scales = ["", "thousand", "million", "billion"]

    def helper(num: int) -> str:
        if 0 <= num < 10:
            return units[num]
        elif 10 <= num < 20:
            return teens[num - 10]
        elif 20 <= num < 100:
            ten_part = tens[num // 10]
            unit_part = num % 10
            if unit_part > 0:
                return f"{ten_part}-{unit_part}"
            return ten_part
        elif 100 <= num < 1000:
            hundred_part = units[num // 100]
            remainder = num % 100
            if remainder == 0:
                return f"{hundred_part} hundred"
            elif 10 <= remainder < 20:
                return f"{hundred_part} hundred {teens[remainder - 10]}"
            elif remainder > 0:
                # Handle cases like "one hundred five" or "one hundred twenty-one"
                sub_words = helper(remainder)
                return f"{hundred_part} hundred {sub_words}"
            else:
                return f"{hundred_part} hundred"
        return ""

    parts = []
    temp_n = n
    for i in range(len(scales) - 1, -1, -1):
        scale_val = 10 ** (3 * i)
        chunk = temp_n // scale_val
        if chunk > 0:
            # Process the chunk (0-999)
            chunk_str = ""
            if chunk == 100:
                chunk_str = "one hundred"
            elif chunk > 100:
                chunk_str = f"{units[chunk // 100]} hundred"
                remainder = chunk % 100
                if remainder > 0:
                    chunk_str += f" {helper(remainder)}"
            else:
                chunk_str = helper(chunk)

            if scales[i]:
                parts.append(f"{chunk_str} {scales[i]}")
            else:
                parts.append(chunk_str)

        temp_n %= scale_val

    # The logic above processes chunks from largest to smallest, 
    # so we join them in order.
    # Note: Because we used a descending range for the loop, 
    # parts are appended in order of largest scale to smallest.
    return " ".join(parts).replace("  ", " ").strip()

# Re-implementing logic slightly more cleanly to ensure order and correct spacing
def number_to_words(n: int) -> str:
    if not isinstance(n, int) or n < 0 or n > 999_999_999_999:
        raise ValueError("Input must be an integer between 0 and 999,999,999,999.")

    if n == 0:
        return "zero"

    units = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    teens = ["ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"]
    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
    scales = ["", "thousand", "million", "billion"]

    def get_chunk_words(num: int) -> str:
        if num == 0:
            return ""
        res = ""
        if num >= 100:
            res += units[num // 100] + " hundred"
            num %= 100
            if num > 0:
                res += " "

        if 10 <= num < 20:
            res += teens[num - 10]
        elif num >= 20:
            res += tens[num // 10]
            if num % 10 > 0:
                res += "-" + units[num % 10]
        else:
            if num > 0:
                res += units[num]
        return res

    result_parts = []
    current_val = n
    for i in range(3, -1, -1):
        scale_power = 10 ** (3 * i)
        chunk = current_val // scale_power
        if chunk > 0:
            chunk_str = get_chunk_words(chunk)
            if scales[i]:
                result_parts.append(f"{chunk_str} {scales[i]}")
            else:
                result_parts.append(chunk_str)
        current_val %= scale_power

    return " ".join(result_parts).replace("  ", " ").strip()
