/**
 * Parses a URL query string into a plain object without using URLSearchParams or URL.
 * Handles multiple values, '+' as spaces, and protects against prototype pollution.
 *
 * @param {string} query - The query string (e.g., "?key=value&key2=val2&key2=val3")
 * @returns {Object} The parsed query object
 */
export function parseQuery(query) {
  const result = Object.create(null);

  if (!query || typeof query !== 'string') {
    return result;
  }

  // Remove leading '?' if present
  const queryString = query.startsWith('?') ? query.slice(1) : query;
  if (!queryString) {
    return result;
  }

  const pairs = queryString.split('&');

  for (let i = 0; i < pairs.length; i++) {
    const pair = pairs[i];
    if (!pair) continue;

    const index = pair.indexOf('=');
    let rawKey, rawValue;

    if (index === -1) {
      rawKey = pair;
      rawValue = '';
    } else {
      rawKey = pair.substring(0, index);
      rawValue = pair.substring(index + 1);
    }

    const key = decodeComponent(rawKey);
    const value = decodeComponent(rawValue);

    // Security: Prevent prototype pollution
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
      continue;
    }

    if (Object.prototype.hasOwnProperty.call(result, key)) {
      const existing = result[key];
      if (Array.isArray(existing)) {
        existing.push(value);
      } else {
        result[key] = [existing, value];
      }
    } else {
      result[key] = value;
    }
  }

  return result;
}

/**
 * Decodes a URI component manually, handling '+' as space and 
 * preserving text on failed percent-decoding.
 * 
 * @param {string} str - The string to decode
 * @returns {string} The decoded string
 */
function decodeComponent(str) {
  if (typeof str !== 'string') return '';

  // Replace '+' with space first
  const plusDecoded = str.replace(/\+/g, ' ');

  try {
    // decodeURIComponent handles percent-encoding
    return decodeURIComponent(plusDecoded);
  } catch (e) {
    // If decodeURIComponent fails (e.g. malformed % sequence),
    // return the string with '+' already replaced by space.
    return plusDecoded;
  }
}
