/**
 * Deeply compares two values for structural equality.
 * Handles primitives, Arrays, Dates, Plain Objects, and Cyclic structures.
 * 
 * @param {any} a - The first value to compare.
 * @param {any} b - The second value to compare.
 * @param {WeakMap} [memo=new WeakMap()] - Internal cache for handling cyclic references.
 * @returns {boolean} True if values are structurally equal.
 */
export function deepEqual(a, b, memo = new WeakMap()) {
  // SameValueZero comparison for primitives
  // Handles NaN === NaN and 0 === -0
  if (Object.is(a, b)) {
    return true;
  }

  // If either is not an object (and not equal by Object.is), they are not equal.
  // Also handles null (typeof null === 'object').
  if (typeof a !== 'object' || a === null || typeof b !== 'object' || b === null) {
    return false;
  }

  // Check if types/constructors match.
  // This ensures [1] !== {0: 1} and Date !== Object etc.
  if (Object.prototype.toString.call(a) !== Object.prototype.toString.call(b)) {
    return false;
  }

  // Handle Date objects
  if (a instanceof Date && b instanceof Date) {
    return a.getTime() === b.getTime();
  }

  // Handle Cyclic Structures
  // We use a WeakMap to track pairs of objects we are currently comparing.
  // If we encounter a pair we've already seen in the current recursion stack, 
  // we assume they are equal for the sake of the cycle.
  if (memo.has(a) && memo.get(a) === b) {
    return true;
  }
  memo.set(a, b);

  // Handle Arrays
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) {
      return false;
    }
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i], memo)) {
        return false;
      }
    }
    return true;
  }

  // Handle Plain Objects
  // Note: We've already checked that both are objects and same type via toString check.
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);

  if (keysA.length !== keysB.length) {
    return false;
  }

  // Every key in A must exist in B and have the same deep value.
  // Using a Set for keysB to ensure O(1) lookup if keys are many, 
    // though Object.keys() length check and loop is standard.
  const keysSetB = new Set(keysB);
  for (const key of keysA) {
    if (!keysSetB.has(key)) {
      return false;
    }
    if (!deepEqual(a[key], b[key], memo)) {
      return false;
    }
  }

  return true;
}
