/**
 * Evaluates an arithmetic expression and returns a number.
 * Supports: +, -, *, /, (), unary +, -, decimal numbers.
 * Throws SyntaxError for malformed inputs.
 * Throws RangeError on division by zero.
 * 
 * @param {string} expression - The arithmetic expression to evaluate.
 * @returns {number} - The result of the evaluation.
 * @throws {SyntaxError} - If the expression is malformed.
 * @throws {RangeError} - If division by zero occurs.
 */
export function evaluate(expression) {
    if (typeof expression !== 'string') {
        throw new SyntaxError("Input must be a string");
    }

    const tokens = tokenize(expression);
    if (tokens.length === 0) {
        throw new SyntaxError("Empty expression");
    }

    let pos = 0;

    // Helper to consume tokens
    function peek() {
        return tokens[pos];
    }

    function consume() {
        return tokens[pos++];
    }

    /**
     * Parser for expressions (Lowest precedence: + and -)
     */
    function parseExpression() {
        let node = parseTerm();
        while (pos < tokens.length && (peek() === '+' || peek() === '-')) {
            const operator = consume();
            const right = parseTerm();
            if (operator === '+') {
                node = node + right;
            } else {
                node = node - right;
            }
        }
        return node;
    }

    /**
     * Parser for terms (Medium precedence: * and /)
     */
    function parseTerm() {
        let node = parseUnary();
        while (pos < tokens.length && (peek() === '*' || peek() === '/')) {
            const operator = consume();
            const right = parseUnary();
            if (operator === '*') {
                node = node * right;
            } else {
                if (right === 0) throw new RangeError("Division by zero");
                node = node / right;
            }
        }
        return node;
    }

    /**
     * Parser for unary operators
     */
    function parseUnary() {
        const token = peek();
        if (token === '-' || token === '+') {
            consume();
            const value = parseUnary();
            return token === '-' ? -value : value;
        }
        return parseFactor();
    }

    /**
     * Parser for factors (Parentheses and Numbers)
     */
    function parseFactor() {
        const token = consume();

        if (token === '(') {
            const result = parseExpression();
            const closing = consume();
            if (closing !== ')') {
                throw new SyntaxError("Missing closing parenthesis");
            }
            return result;
        }

        if (typeof token === 'number') {
            return token;
        }

        throw new SyntaxError(`Unexpected token: ${token}`);
    }

    const result = parseExpression();

    if (pos < tokens.length) {
        throw new SyntaxError(`Unexpected token at end: ${tokens[pos]}`);
    }

    return result;
}

/**
 * Tokenizes the input string into numbers, operators, and parentheses.
 */
function tokenize(str) {
    const tokens = [];
    let i = 0;

    while (i < str.length) {
        const char = str[i];

        if (/\s/.test(char)) {
            i++;
            continue;
        }

        if (/[0-9.]/.test(char)) {
            let numStr = "";
            while (i < str.length && /[0-9.]/.test(str[i])) {
                // Handle multiple dots by validating
                if (str[i] === '.' && numStr.includes('.')) {
                    break; 
                }
                numStr += str[i];
                i++;
            }
            const num = parseFloat(numStr);
            if (isNaN(num)) {
                throw new SyntaxError(`Invalid number format at index ${i}`);
            }
            tokens.push(num);
            continue;
        }

        if ("+-*/()".includes(char)) {
            tokens.push(char);
            i++;
            continue;
        }

        throw new SyntaxError(`Unknown character: ${char}`);
    }

    return tokens;
}
