/**
 * Formats a byte count with binary (IEC) units (KiB, MiB, etc.).
 *
 * @param {number} bytes - The number of bytes to format.
 * @param {number} [decimals=1] - The number of decimal places to display.
 * @returns {string} The formatted string (e.g., "1.5 KiB").
 * @throws {TypeError} If bytes is not a finite number.
 * @throws {RangeError} If decimals is not an integer between 0 and 10.
 */
export function formatBytes(bytes, decimals = 1) {
  if (typeof bytes !== 'number' || !Number.isFinite(bytes)) {
    throw new TypeError('The bytes argument must be a finite number.');
  }

  if (!Number.isInteger(decimals) || decimals < 0 || decimals > 10) {
    throw new RangeError('The decimals argument must be an integer between 0 and 10.');
  }

  const units = ['B', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB'];
  const factor = 1024;

  // Handle the zero case or small values
  if (Math.abs(bytes) < factor) {
    return `${Math.floor(bytes)} B`;
  }

  const absBytes = Math.abs(bytes);
  let unitIndex = 0;
  let value = absBytes;

  // Find the largest unit where value >= 1
  // We iterate up to PiB (index 5)
  while (value >= factor && unitIndex < units.length - 1) {
    value /= factor;
    unitIndex++;
  }

  // Rounding check: If rounding the value results in 1024.0,
  // we must shift to the next unit to avoid displaying "1024.0 KiB".
  // This is checked because the current 'value' might be 1023.99...
  // and rounding to X decimals makes it 1024.0.
  let finalValue = value;
  let finalUnitIndex = unitIndex;

  // Check if rounding results in 1024
  // We use a small epsilon to account for floating point precision
  const rounded = Number(finalValue.toFixed(decimals));
  if (rounded >= factor && finalUnitIndex < units.length - 1) {
    finalValue /= factor;
    finalUnitIndex++;
  }

  const sign = bytes < 0 ? '-' : '';
  const formattedNumber = finalValue.toFixed(decimals);

  // If the decimal part is .00, we still keep the decimal point as per "exactly decimals digits"
  // but some implementations might prefer to strip it. The prompt specifies "exactly decimals digits".
  return `${sign}${formattedNumber} ${units[finalUnitIndex]}`;
}
