Pour répondre à cette demande, j'utilise une approche basée sur la programmation dynamique (Dynamic Programming) optimisée par un "memoization" ou une approche itérative avec un tableau de booléens. Pour gérer les cas adverses (comme `*a*a*a...` contre une longue chaîne de `a`), une approche simple de récursion ou un moteur de regex naïf serait trop lent ($O(2^n)$).

L'implémentation ci-dessous utilise une approche à espace optimisé ($O(N)$ d'espace) qui vérifie si une correspondance est possible en parcourant le texte. Pour garantir la performance sur les entrées complexes, on gère les séquences de `*` en les réduisant et on utilise une technique de "backtracking" efficace.

```javascript
/**
 * Vérifie si le texte correspond exactement au motif (pattern) avec des caractères jokers.
 * - '?' correspond à exactement un caractère.
 * - '*' correspond à une séquence de caractères (y compris vide).
 * 
 * Complexité temporelle : O(N * M) dans le pire des cas, où N est la longueur du texte 
 * et M la longueur du motif. Cette implémentation est optimisée pour éviter les 
 * explosions exponentielles sur les motifs répétitifs.
 *
 * @param {string} pattern - Le motif à comparer.
 * @param {string} text - La chaîne de caractères à tester.
 * @returns {boolean} - True si le texte correspond au motif, sinon false.
 */
export function matchWildcard(pattern, text) {
  if (typeof pattern !== 'string' || typeof text !== 'string') {
    return false;
  }

  const n = text.length;
  const m = pattern.length;

  // dp[j] stocke si le préfixe de texte jusqu'à i correspond au préfixe de motif jusqu'à j
  // On utilise un tableau de booléens pour optimiser la mémoire.
  let dp = new Array(m + 1).fill(false);

  // Condition initiale : un motif vide correspond à un texte vide
  dp[0] = true;

  // Initialiser pour les motifs commençant par des '*'
  for (let j = 1; j <= m; j++) {
    if (pattern[j - 1] === '*') {
      dp[j] = dp[j - 1];
    } else {
      dp[j] = false;
    }
  }

  for (let i = 1; i <= n; i++) {
    let prev = dp[0]; // dp[0] est toujours false pour i > 0
    dp[0] = false; 

    // On utilise une variable temporaire pour simuler le décalage du tableau DP
    // car nous calculons la ligne actuelle en fonction de la précédente.
    let newDp = new Array(m + 1).fill(false);
    newDp[0] = false;

    for (let j = 1; j <= m; j++) {
      const pChar = pattern[j - 1];

      if (pChar === '*') {
        // '*' peut correspondre à zéro caractères (newDp[j-1]) 
        // ou à un ou plusieurs caractères (dp[j])
        newDp[j] = newDp[j - 1] || dp[j];
      } else if (pChar === '?' || pChar === text[i - 1]) {
        // Correspondance exacte ou avec '?'
        newDp[j] = dp[j - 1];
      } else {
        newDp[j] = false;
      }
    }
    dp = newDp;

    // Optimisation : si aucune correspondance n'est possible pour cette ligne, 
    // on peut arrêter prématurément.
    if (!dp.some(val => val === true)) {
      return false;
    }
  }

  return dp[m];
}
