/**
 * Searches for the first and last position of a target element in a sorted array.
 * Runs in O(log n) time using binary search.
 * 
 * @param {number[]} sorted - An array of integers sorted in ascending order.
 * @param {number} target - The number to search for.
 * @returns {[number, number]} The first and last indices of the target, or [-1, -1].
 */
export function searchRange(sorted, target) {
  if (!Array.isArray(sorted) || sorted.length === 0) {
    return [-1, -1];
  }

  const findBound = (isFirst) => {
    let low = 0;
    let high = sorted.length - 1;
    let result = -1;

    while (low <= high) {
      const mid = Math.floor(low + (high - low) / 2);

      if (sorted[mid] === target) {
        result = mid;
        if (isFirst) {
          high = mid - 1; // Keep looking left
        } else {
          low = mid + 1; // Keep looking right
        }
      } else if (sorted[mid] < target) {
        low = mid + 1;
      } else {
        high = mid - 1;
      }
    }

    return result;
  };

  const first = findBound(true);
  if (first === -1) {
    return [-1, -1];
  }
  const last = findBound(false);

  return [first, last];
}
