def merge_intervals(intervals):
    if not intervals:
        return []

    # Validate and check for invalid intervals (start > end)
    for start, end in intervals:
        if not isinstance(start, int) or not isinstance(end, int) or start > end:
            raise ValueError("All intervals must be tuples of integers where start <= end.")

    # Sort intervals by start
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = [sorted_intervals[0]]

    for current in sorted_intervals[1:]:
        last = merged[-1]
        # Check if current overlaps or touches the last merged interval
        if current[0] <= last[1]:
            # Merge them by updating the end of the last interval
            last[1] = max(last[1], current[1])
        else:
            # No overlap, append current interval
            merged.append(current)

    return merged
