def roman_to_int(s: str) -> int:
    """
    Converts a canonical Roman numeral string to an integer.

    Supports values from 1 to 3999 using standard subtractive pairs.
    Raises ValueError for invalid inputs (empty, lowercase, unknown chars,
    or non-canonical forms like 'IIII', 'VV', etc.).
    """
    if not isinstance(s, str) or s == "":
        raise ValueError("Invalid input: empty or non-string")

    if s != s.upper():
        raise ValueError("Invalid input: lowercase letters not allowed")

    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }

    valid_roman_chars = set(roman_map.keys())

    for char in s:
        if char not in valid_roman_chars:
            raise ValueError(f"Invalid character: {char}")

    if len(s) == 1:
        return roman_map[s[0]]

    total = 0
    prev_value = 0

    for i in range(len(s) - 1, -1, -1):
        curr_value = roman_map[s[i]]

        if curr_value < prev_value:
            total -= curr_value
        else:
            total += curr_value

        prev_value = curr_value

    # Additional validation for non-canonical forms
    # Check for repeated values that shouldn't occur in canonical form
    # (e.g., 'IIII', 'VV', 'XXXX', 'LL', 'CC', 'DD', 'MMMM')
    # Note: 'III' is valid (3), but 'IIII' is not.
    # We can detect this by checking if any value appears more than its canonical limit.

    # Count occurrences of each numeral
    counts = {'I': 0, 'V': 0, 'X': 0, 'L': 0, 'C': 0, 'D': 0, 'M': 0}
    for char in s:
        counts[char] += 1

    # Canonical limits: I<=3, V=1, X<=3, L=1, C<=3, D=1, M<=3
    limits = {'I': 3, 'V': 1, 'X': 3, 'L': 1, 'C': 3, 'D': 1, 'M': 3}
    for char, count in counts.items():
        if count > limits[char]:
            raise ValueError(f"Non-canonical form: '{char}' appears {count} times")

    return total
