def compare_versions(a: str, b: str) -> int:
    """
    Compare two Semantic Versioning 2.0.0 strings.

    Returns:
        -1 if a < b
         0 if a == b
         1 if a > b

    SemVer format: MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]
    Build metadata is ignored.
    """
    import re

    def parse_version(version_str: str) -> dict:
        """Parse a SemVer string into its components."""
        match = re.match(r'^(?P<major>\d+)(?:\.(?P<minor>\d+)(?:\.(?P<patch>\d+))?)?(?:(?P<pre>-[^+]*)(?:\+[^.]*)?)?(?:(?P<build>\+[^+]*))?(?:\.[0-9A-Za-z-]+)*$', version_str)
        if not match:
            raise ValueError(f"Invalid SemVer string: {version_str}")

        major = int(match.group('major')) if match.group('major') is not None else 0
        minor = int(match.group('minor')) if match.group('minor') is not None else 0
        patch = int(match.group('patch')) if match.group('patch') is not None else 0

        pre_release = match.group('pre')
        build_metadata = match.group('build') if match.group('build') is not None else None

        return {
            'major': major,
            'minor': minor,
            'patch': patch,
            'prerelease': pre_release,
            'build': build_metadata
        }

    def compare_identifiers(id_a: str, id_b: str) -> int:
        """Compare two identifiers according to SemVer rules."""
        # Split identifiers by dot
        ids_a = id_a.split('.')
        ids_b = id_b.split('.')

        # Compare length first if one is a prefix of the other
        if len(ids_a) < len(ids_b):
            return -1
        elif len(ids_a) > len(ids_b):
            return 1

        # Compare identifiers one by one
        for i in range(len(ids_a)):
            idx_a = ids_a[i]
            idx_b = ids_b[i]

            # Check if both are numeric
            if idx_a.isdigit() and idx_b.isdigit():
                num_a = int(idx_a)
                num_b = int(idx_b)
                if num_a < num_b:
                    return -1
                elif num_a > num_b:
                    return 1
            else:
                # Compare as strings (ASCII order)
                if idx_a < idx_b:
                    return -1
                elif idx_a > idx_b:
                    return 1

        return 0

    def compare_pre_release(pre_a: str, pre_b: str) -> int:
        """Compare pre-release versions."""
        if pre_a is None and pre_b is None:
            return 0
        elif pre_a is None:
            return 1  # Normal version has higher precedence than pre-release
        elif pre_b is None:
            return -1  # Pre-release has lower precedence than normal version

        ids_a = pre_a.split('.')
        ids_b = pre_b.split('.')

        for i in range(max(len(ids_a), len(ids_b))):
            if i >= len(ids_a):
                return -1  # Shorter pre-release is lower
            elif i >= len(ids_b):
                return 1   # Longer pre-release is higher

            cmp = compare_identifiers(ids_a[i], ids_b[i])
            if cmp != 0:
                return cmp

        return 0

    def normalize_pre_release(pre_str: str) -> str:
        """Normalize pre-release string to ensure consistent comparison."""
        # Replace any non-alphanumeric characters with dots for splitting
        normalized = []
        for char in pre_str:
            if char == '-':
                continue
            elif char in '.':
                normalized.append(char)
            else:
                normalized.append(char)
        return '.'.join(normalized)

    def compare_build(build_a: str, build_b: str) -> int:
        """Build metadata is ignored according to SemVer, but we need to handle the case where it's present."""
        # According to SemVer: "Build metadata MUST be ignored when comparing versions"
        # So we don't actually compare build metadata
        return 0

    # Parse both versions
    try:
        version_a = parse_version(a)
        version_b = parse_version(b)
    except ValueError as e:
        raise ValueError(f"Invalid SemVer string: {e}")

    # Compare major, minor, patch
    if version_a['major'] < version_b['major']:
        return -1
    elif version_a['major'] > version_b['major']:
        return 1

    if version_a['minor'] < version_b['minor']:
        return -1
    elif version_a['minor'] > version_b['minor']:
        return 1

    if version_a['patch'] < version_b['patch']:
        return -1
    elif version_a['patch'] > version_b['patch']:
        return 1

    # Compare pre-release
    cmp_pre = compare_pre_release(version_a['prerelease'], version_b['prerelease'])

    # If pre-release comparison is not 0, return that result
    if cmp_pre != 0:
        return cmp_pre

    # If pre-release comparison is 0, versions are equal
    return 0
