def parse_csv_line(line):
    fields = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Start of a quoted field
            i += 1
            field = []
            while i < n:
                if line[i] == '"':
                    # Check for escaped quote
                    if i + 1 < n and line[i + 1] == '"':
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        if i + 1 < n and line[i + 1] == ',':
                            i += 1
                        else:
                            raise ValueError("Unterminated quoted field")
                        break
                else:
                    field.append(line[i])
                    i += 1
            fields.append(''.join(field))
        elif line[i] == ',':
            fields.append('')
            i += 1
        else:
            # Unquoted field
            if line[i] == '\n':
                fields.append('')
                i += 1
            else:
                # Read until comma or newline/end
                j = i
                while j < n and line[j] != ',' and line[j] != '\n':
                    j += 1
                if j < n and line[j] == ',':
                    i = j + 1
                else:
                    i = j
                fields.append(line[i:j])

    return fields
