def longest_common_subsequence(a: str, b: str) -> str:
    """
    Returns one longest common subsequence of strings a and b.
    Handles strings up to ~2000 characters efficiently using dynamic programming.
    Time complexity: O(n*m), Space complexity: O(n*m)
    """
    if not a or not b:
        return ""

    n, m = len(a), len(b)

    # Create DP table
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Fill DP table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Reconstruct the subsequence by backtracking
    result = []
    i, j = n, m
    while i > 0 and j > 0:
        if a[i - 1] == b[j - 1]:
            result.append(a[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] >= dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    return ''.join(reversed(result))
