def number_to_words(n: int) -> str:
    if not (0 <= n <= 999_999_999_999):
        raise ValueError("Number must be between 0 and 999,999,999,999 inclusive.")

    under_thousand = [
        "", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
        "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
        "seventeen", "eighteen", "nineteen",
        "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"
    ]

    def spell_under_thousand(num: int) -> str:
        if num == 0:
            return ""
        if num < 20:
            return under_thousand[num]

        parts = []
        if num >= 100:
            parts.append(under_thousand[num // 100] + " hundred")
            num %= 100
        if num >= 20:
            tens = num // 10
            ones = num % 10
            if ones == 0:
                parts.append(under_thousand[tens])
            else:
                if tens == 1:
                    parts.append(under_thousand[num])
                else:
                    parts.append(under_thousand[tens] + "-" + under_thousand[ones])
        return " ".join(parts)

    scale_words = ["", " thousand", " million", " billion"]

    result_parts = []
    chunks = [n // 1_000_000_000, n // 1_000_000 % 1_000, n // 1_000 % 1_000, n % 1_000]

    for i, chunk in enumerate(chunks):
        if chunk > 0:
            spelled = spell_under_thousand(chunk) + scale_words[i]
            result_parts.append(spelled)

    return " ".join(result_parts) if result_parts else under_thousand[0]
