def slugify(text: str, max_length: int = 50) -> str:
    if max_length < 1:
        raise ValueError("max_length must be at least 1")

    # Mapping for special characters
    accented_chars = {
        'é': 'e', 'è': 'e', 'ê': 'e', 'ë': 'e',
        'ñ': 'n', 'ü': 'u', 'Ü': 'u',
        'ß': 'ss', 'æ': 'ae', 'œ': 'oe', 'ø': 'o'
    }

    # Normalize accents and map special characters
    normalized = text
    for acc, repl in accented_chars.items():
        normalized = normalized.replace(acc, repl)

    # Replace non-alphanumeric characters with hyphens
    slug = []
    prev_is_alpha_num = False

    for char in normalized:
        if char.isalnum():
            if not prev_is_alpha_num:
                slug.append(char)
            prev_is_alpha_num = True
        else:
            if slug and not prev_is_alpha_num:
                # Append hyphen only if it's not a leading hyphen
                if slug[-1] != '-':
                    slug.append('-')
                else:
                    # Skip consecutive hyphens
                    continue
            else:
                # Start of a new run of non-alphanumeric chars
                if slug and prev_is_alpha_num:
                    # Ensure no leading hyphen
                    if slug[-1] == '-':
                        slug.pop()
                slug.append('-')
                prev_is_alpha_num = False

    # Clean up trailing hyphens
    while slug and slug[-1] == '-':
        slug.pop()

    return ''.join(slug)[:max_length]
