def convert_base(number, from_base, to_base):
    if from_base < 2 or from_base > 36 or to_base < 2 or to_base > 36:
        raise ValueError("Base must be between 2 and 36.")

    if not number or number.strip() == "-":
        raise ValueError("Input string is empty or invalid.")

    if number[0] == "-":
        is_negative = True
        number = number[1:]
    else:
        is_negative = False

    if number == "":
        raise ValueError("Input string is empty or invalid.")

    digits_map = {str(i): i for i in range(10)}
    digits_map.update({chr(i): i - 10 for i in range(ord('a'), ord('z') + 1)})
    digits_map.update({chr(i): i - 10 for i in range(ord('A'), ord('Z') + 1)})

    to_digits_map = {i: str(i) for i in range(36)}

    try:
        value = 0
        for char in number:
            if char not in digits_map:
                raise ValueError(f"Invalid digit '{char}' for base {from_base}.")
            digit_val = digits_map[char]
            if digit_val >= from_base:
                raise ValueError(f"Invalid digit '{char}' for base {from_base}.")
            value = value * from_base + digit_val
    except ValueError:
        if is_negative:
            raise ValueError(f"Invalid digit '{number[0]}' or invalid digit for base {from_base} in string '{number}'.")
        raise ValueError(f"Invalid digit '{number[0]}' or invalid digit for base {from_base} in string '{number}'.")

    if value == 0:
        return "0"

    result_digits = []
    while value > 0:
        remainder = value % to_base
        result_digits.append(to_digits_map[remainder])
        value = value // to_base

    result = ''.join(reversed(result_digits))

    if is_negative:
        result = "-" + result

    return result
