export function parseQuery(query) {
    if (typeof query !== 'string') {
        return {};
    }

    const result = {};

    // Remove leading "?" if present
    const cleanQuery = query.startsWith('?') ? query.slice(1) : query;

    // Split by "&"
    const pairs = cleanQuery.split('&');

    for (const pair of pairs) {
        // Ignore empty pairs
        if (pair.length === 0) {
            continue;
        }

        // Split on the first "="
        const eqIndex = pair.indexOf('=');
        let key, value;

        if (eqIndex === -1) {
            // No "=", key maps to empty string
            key = pair;
            value = '';
        } else {
            key = pair.slice(0, eqIndex);
            value = pair.slice(eqIndex + 1);
        }

        // Decode key and value
        key = decodeURIComponent(key);
        value = decodeURIComponent(value);

        // Handle "+" as space before/after percent-decoding (standard behavior)
        // The above decodeURIComponent handles "%20" -> " ", but we also need "+" -> " "
        // Since decodeURIComponent does not replace "+", we do it manually after decoding.
        key = key.replace(/\+/g, ' ');
        value = value.replace(/\+/g, ' ');

        // Set value in result (handles multiple occurrences)
        if (result[key] instanceof Array) {
            result[key].push(value);
        } else {
            result[key] = value;
        }
    }

    return result;
}
