export function deepEqual(a, b) {
  if (a === b) return true;

  if (a == null || b == null) return false;

  const typeA = typeof a;
  const typeB = typeof b;

  if (typeA !== typeB) return false;

  if (typeA === 'number' || typeA === 'boolean') {
    // SameValueZero: NaN equals NaN, 0 equals -0
    if (a !== a && b !== b) return true; // both NaN
    return Number(a) === Number(b);
  }

  if (typeA === 'string' || typeA === 'symbol' || typeA === 'undefined') {
    return String(a) === String(b);
  }

  if (typeA === 'function') {
    return false; // Functions are never equal by value in this context
  }

  if (typeA === 'bigint') {
    return String(a) === String(b);
  }

  if (typeA === 'date') {
    return a.getTime() === b.getTime();
  }

  if (typeA === 'array') {
    if (!Array.isArray(b)) return false;
    if (a.length !== b.length) return false;

    let i = 0;
    while (i < a.length) {
      if (!deepEqual(a[i], b[i])) return false;
      i++;
    }
    return true;
  }

  if (typeA === 'object') {
    if (!b || !b.constructor || b.constructor !== Object) return false;
    if (Object.keys(a).length !== Object.keys(b).length) return false;

    const keysA = Object.keys(a);
    const keysB = Object.keys(b);

    // Check if keys are the same (order doesn't matter, but set equality does)
    if (keysA.length !== keysB.length) return false;

    const keySetA = new Set(keysA);
    const keySetB = new Set(keysB);

    if (!keySetA.every(k => keySetB.has(k))) return false;

    for (const key of keysA) {
      if (!deepEqual(a[key], b[key])) return false;
    }

    return true;
  }

  return false;
}
