export function formatBytes(bytes, decimals = 1) {
  if (!Number.isFinite(bytes)) {
    throw new TypeError('bytes must be a finite number');
  }

  if (typeof decimals !== 'number' || !Number.isInteger(decimals) || decimals < 0 || decimals > 10) {
    throw new RangeError('decimals must be an integer from 0 to 10');
  }

  const units = ['B', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB'];
  const factor = 1024;
  let value = bytes;
  let unitIndex = 0;

  while (Math.abs(value) >= factor && unitIndex < units.length - 1) {
    value /= factor;
    unitIndex++;
  }

  if (unitIndex === 0) {
    return Math.abs(value).toFixed(0) + ' B';
  }

  const formattedValue = value.toFixed(decimals);
  const parsedValue = parseFloat(formattedValue);

  if (parsedValue >= factor && unitIndex < units.length - 1) {
    return formatBytes(bytes * factor, decimals);
  }

  return formattedValue + ' ' + units[unitIndex];
}
