/**
 * Matches a wildcard pattern against a text.
 * - "?" matches exactly one character.
 * - "*" matches any sequence of characters (including empty).
 * - Other characters must match exactly (no escaping, no character classes).
 *
 * Uses an efficient two-pointer approach with backtracking for '*' to avoid
 * exponential time complexity on adversarial inputs like "*****" vs "aaaa...".
 *
 * @param {string} pattern - The wildcard pattern.
 * @param {string} text - The text to match against.
 * @returns {boolean} True if the entire text matches the entire pattern, false otherwise.
 */
export function matchWildcard(pattern, text) {
    if (typeof pattern !== 'string' || typeof text !== 'string') {
        return false;
    }

    const pLen = pattern.length;
    const tLen = text.length;

    if (pLen === 0 && tLen === 0) {
        return true;
    }
    if (pLen === 0 || tLen === 0) {
        return false;
    }

    let pIdx = 0;
    let tIdx = 0;
    let starIdx = -1;
    let starStart = -1;

    while (tIdx < tLen) {
        if (pIdx < pLen && (pattern[pIdx] === '?' || pattern[pIdx] === text[tIdx])) {
            pIdx++;
            tIdx++;
        } else if (pIdx < pLen && pattern[pIdx] === '*') {
            starIdx = pIdx;
            starStart = tIdx;
            pIdx++;
            tIdx++; // Consume one character from text to try to match '*'
        } else {
            // Backtrack: if we hit a '*' earlier, try to match more text with it
            if (starIdx === -1) {
                return false;
            }

            // Move '*' to cover one less character in text
            pIdx = starIdx + 1;
            tIdx = starStart;
        }
    }

    // At the end, all text must be consumed.
    // The pattern may still have '*' characters at the end, which match the empty string.
    // We need to ensure that any remaining '*' in the pattern can consume the rest of the pattern (if any)
    // but since we are matching the whole text, the pattern must be fully consumed or consist of trailing '*'s.
    // Actually, the logic above ensures that if we finish the text, the remaining pattern must be all '*'s.
    // Let's verify if the rest of the pattern is valid (only '*').

    while (pIdx < pLen && pattern[pIdx] === '*') {
        pIdx++;
    }

    return pIdx === pLen;
}
