def merge_intervals(intervals):
    # Validate intervals and sort them by start time
    for start, end in intervals:
        if start > end:
            raise ValueError("Invalid interval: start must be <= end")

    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = [sorted_intervals[0]]

    for current in sorted_intervals[1:]:
        last = merged[-1]

        # Check if the current interval overlaps or touches the last merged interval
        if current[0] <= last[1]:
            # Merge the intervals by updating the end of the last interval
            last[1] = max(last[1], current[1])
        else:
            # No overlap, add the current interval to the list
            merged.append(current)

    return merged
