def parse_csv_line(line):
    fields = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Start of a quoted field
            j = i + 1
            while j < n:
                if line[j] == '"':
                    # Check for escaped quote
                    if j + 1 < n and line[j + 1] == '"':
                        fields.append('"')
                        j += 2
                    else:
                        # End of quoted field
                        break
                elif line[j] == ',':
                    # Comma inside quotes is literal, continue reading
                    j += 1
                else:
                    j += 1

            if j >= n:
                raise ValueError("Unterminated quoted field")

            fields.append(line[i:j])
            i = j + 1
        elif line[i] == ',':
            # Separator between fields
            fields.append("")
            i += 1
        else:
            # Regular character, part of an unquoted field
            fields.append(line[i])
            i += 1

    return fields
