def number_to_words(n):
    if n < 0 or n > 999_999_999_999:
        raise ValueError("Input out of range")

    under_thousand = [
        "", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
        "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
        "seventeen", "eighteen", "nineteen",
        "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"
    ]

    hundred_words = [
        "", "one hundred", "two hundred", "three hundred", "four hundred",
        "five hundred", "six hundred", "seven hundred", "eight hundred", "nine hundred"
    ]

    scale_words = ["", "thousand", "million", "billion"]

    def convert_under_thousand(num):
        if num == 0:
            return ""

        result = []

        if num >= 100:
            result.append(hundred_words[num // 100])
            num %= 100

        if num >= 20:
            result.append(under_thousand[num // 10])
            num %= 10
        elif num > 0:
            result.append(under_thousand[num])

        return " ".join(result)

    parts = []

    # Process billions
    if n >= 1_000_000_000:
        parts.append(convert_under_thousand(n // 1_000_000_000))
        n %= 1_000_000_000

    # Process millions
    if n >= 1_000_000:
        parts.append(convert_under_thousand(n // 1_000_000) + " million")
        n %= 1_000_000

    # Process thousands
    if n >= 1_000:
        parts.append(convert_under_thousand(n // 1_000) + " thousand")
        n %= 1_000

    # Process the rest
    if n > 0:
        parts.append(convert_under_thousand(n))

    return " ".join(parts) if parts else "zero"
