import heapq

def shortest_distances(n, edges, source):
    # Validate source node
    if not (0 <= source < n):
        raise ValueError("Source must be a valid node index between 0 and n-1.")

    # Validate edge weights and nodes
    for u, v, weight in edges:
        if not (0 <= u < n and 0 <= v < n):
            raise ValueError("Edge endpoints must be valid node indices.")
        if weight < 0:
            raise ValueError("Edge weights must be non-negative.")

    # Initialize distances with infinity
    distances = [float('inf')] * n
    distances[source] = 0

    # Priority queue stores (distance, u) tuples
    pq = [(0, source)]

    while pq:
        d, u = heapq.heappop(pq)

        # Skip if we've already found a shorter path to this node
        if d > distances[u]:
            continue

        # Iterate over all edges from u
        for v, weight in edges:
            if u == v and weight != 0:
                # Handle self-loops correctly (though typically not needed for shortest path)
                pass

            if distances[v] > d + weight:
                distances[v] = d + weight
                heapq.heappush(pq, (distances[v], v))

    return distances
