def convert_base(number, from_base, to_base):
    if from_base < 2 or from_base > 36 or to_base < 2 or to_base > 36:
        raise ValueError("Base must be between 2 and 36")

    if not number or (len(number) == 1 and number != "-"):
        raise ValueError("Input string cannot be empty or just '-'")

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"

    # Handle negative sign separately
    is_negative = False
    if number.startswith("-"):
        is_negative = True
        number = number[1:]

    if not number:
        raise ValueError("Input string cannot be empty or just '-'")

    # Convert from source base to integer value
    try:
        value = 0
        for char in number:
            if char.lower() not in digits:
                raise ValueError(f"Invalid digit '{char}' for base {from_base}")

            digit_value = digits.index(char.lower())
            if digit_value >= from_base:
                raise ValueError(f"Digit '{char}' is invalid for base {from_base}")

            value = value * from_base + digit_value
    except (ValueError, IndexError):
        raise ValueError("Invalid number format or digit out of range")

    # Handle zero case
    if value == 0:
        result = "0"
    else:
        # Convert to target base
        temp_value = abs(value)
        result_digits = []

        while temp_value > 0:
            remainder = temp_value % to_base
            result_digits.append(digits[remainder])
            temp_value //= to_base

        result = "".join(reversed(result_digits))

    # Apply negative sign if needed
    if is_negative and value != 0:
        result = "-" + result

    return result
