// parseQuery.js
/**
 * Parses a URL query string into a plain object without using URLSearchParams or the URL class.
 * 
 * @param {string} query - The query string to parse (e.g., "a=1&b=2")
 * @returns {Object} - A plain object with parsed key-value pairs
 */
function parseQuery(query) {
  // Handle empty or null/undefined input
  if (!query || typeof query !== 'string') {
    return {};
  }

  // Remove leading '?' if present
  const trimmed = query.startsWith('?') ? query.slice(1) : query;

  // Split pairs by '&'
  const pairs = trimmed.split('&');

  // Map to store results: keys map to arrays, others map to strings
  const result = {};

  for (const pair of pairs) {
    // Skip empty pairs
    if (!pair.trim()) {
      continue;
    }

    // Split on the first '=' only
    const eqIndex = pair.indexOf('=');
    let key, value;

    if (eqIndex === -1) {
      // No '=', key maps to empty string
      key = pair;
      value = '';
    } else {
      key = pair.slice(0, eqIndex);
      value = pair.slice(eqIndex + 1);
    }

    // Decode: replace '+' with space first
    let decodedKey = key.replace(/\+/g, ' ');
    let decodedValue = value.replace(/\+/g, ' ');

    // Percent-decode if there are '%' characters
    if (/[%]/.test(decodedKey) || /[%]/.test(decodedValue)) {
      try {
        // Use a safe decodeURIComponent that doesn't throw on invalid sequences
        decodedKey = decodeURIComponent(decodedKey);
        decodedValue = decodeURIComponent(decodedValue);
      } catch (e) {
        // If decoding fails, keep the original text with '+' already converted to spaces
        // We need to re-encode the safe parts and append the unsafe part
        const safePart = decodedKey.replace(/%[0-9A-Fa-f]{2}/g, '');
        const unsafePart = decodedKey.replace(/%[0-9A-Fa-f]{2}/g, '').replace(/\+/g, ' ');

        // Actually, let's just keep the text as is with '+' -> space
        // The requirement says: "If percent-decoding fails, keep that text as it is (with "+" still turned into spaces)"
        // So we revert to the version after + replacement but before decoding
        decodedKey = key.replace(/\+/g, ' ');
        decodedValue = value.replace(/\+/g, ' ');
      }
    }

    // Handle keys that appear multiple times
    if (result.hasOwnProperty(decodedKey)) {
      result[decodedKey].push(decodedValue);
    } else {
      // Ensure we don't create prototype pollution by using a safe key handling
      // We'll use Object.defineProperty to ensure it's an own property
      const val = decodedValue;

      // Check if the key is dangerous (like "__proto__", "constructor", etc.)
      // To prevent prototype pollution, we can use a non-enumerable property or 
      // simply ensure it's set as an own property using Object.defineProperty
      Object.defineProperty(result, decodedKey, {
        value: val,
        writable: true,
        enumerable: true,
        configurable: true
      });
    }
  }

  return result;
}

export { parseQuery };
