// solution.js
export function evaluate(expression) {
    if (!expression || expression.trim() === '') {
        throw new SyntaxError('Empty input');
    }

    const tokens = tokenize(expression);
    if (tokens.length === 0) {
        throw new SyntaxError('Empty input');
    }

    let pos = 0;

    function peek() {
        return tokens[pos];
    }

    function consume() {
        return tokens[pos++];
    }

    function parseUnary() {
        if (peek().kind === 'UNARY_MINUS') {
            const val = parseUnary();
            return -val;
        } else if (peek().kind === 'UNARY_PLUS') {
            consume();
            return parseUnary();
        } else {
            return parsePrimary();
        }
    }

    function parsePrimary() {
        const token = peek();

        if (token.kind === 'NUMBER') {
            const val = parseFloat(token.value);
            if (isNaN(val)) {
                throw new SyntaxError('Invalid number');
            }
            consume();
            return val;
        } else if (token.kind === 'LPAREN') {
            consume(); // consume '('
            const val = parseAdditive();
            if (!peek().kind || peek().kind !== 'RPAREN') {
                throw new SyntaxError('Unbalanced parentheses');
            }
            consume(); // consume ')'
            return val;
        } else {
            throw new SyntaxError(`Unexpected token: ${token.kind}`);
        }
    }

    function parseMultiplicative() {
        let left = parseUnary();

        while (peek().kind === 'MULT' || peek().kind === 'DIV') {
            const op = consume();
            const right = parseUnary();

            if (op.kind === 'MULT') {
                if (right === 0) {
                    throw new RangeError('Division by zero');
                }
                left *= right;
            } else if (op.kind === 'DIV') {
                if (left === 0) {
                    throw new RangeError('Division by zero');
                }
                left /= right;
            }
        }

        return left;
    }

    function parseAdditive() {
        let left = parseMultiplicative();

        while (peek().kind === 'PLUS' || peek().kind === 'MINUS') {
            const op = consume();
            const right = parseMultiplicative();

            if (op.kind === 'PLUS') {
                left += right;
            } else if (op.kind === 'MINUS') {
                left -= right;
            }
        }

        return left;
    }

    function parseExpression() {
        const result = parseAdditive();
        if (!peek().kind) {
            throw new SyntaxError('Dangling operator');
        }
        return result;
    }

    try {
        const result = parseExpression();
        return Number.isFinite(result) ? result : NaN;
    } catch (e) {
        if (e instanceof SyntaxError || e instanceof RangeError) {
            throw e;
        }
        throw new SyntaxError('Parse error');
    }
}

function tokenize(expression) {
    const tokens = [];
    let i = 0;
    const len = expression.length;

    while (i < len) {
        const char = expression[i];

        if (char === ' ') {
            i++;
            continue;
        }

        if (char === '(') {
            tokens.push({ kind: 'LPAREN', value: '(' });
            i++;
            continue;
        }

        if (char === ')') {
            tokens.push({ kind: 'RPAREN', value: ')' });
            i++;
            continue;
        }

        if (char === '+') {
            // Check for unary plus
            const next = expression[i + 1];
            if (next === '-' || next === '*' || next === '/' || next === '(') {
                tokens.push({ kind: 'UNARY_PLUS', value: '+' });
                i++;
                continue;
            } else {
                throw new SyntaxError('Unexpected character');
            }
        }

        if (char === '-') {
            // Check for unary minus
            const next = expression[i + 1];
            if (next === '-' || next === '*' || next === '/' || next === '(') {
                tokens.push({ kind: 'UNARY_MINUS', value: '-' });
                i++;
                continue;
            } else {
                throw new SyntaxError('Unexpected character');
            }
        }

        if (char === '*') {
            tokens.push({ kind: 'MULT', value: '*' });
            i++;
            continue;
        }

        if (char === '/') {
            tokens.push({ kind: 'DIV', value: '/' });
            i++;
            continue;
        }

        if (char === '+') {
            // Check for binary plus
            const prev = tokens[tokens.length - 1];
            if (!prev || prev.kind !== 'NUMBER' && prev.kind !== 'LPAREN') {
                throw new SyntaxError('Unexpected character');
            }
            tokens.push({ kind: 'PLUS', value: '+' });
            i++;
            continue;
        }

        if (char === '-') {
            // Check for binary minus
            const prev = tokens[tokens.length - 1];
            if (!prev || prev.kind !== 'NUMBER' && prev.kind !== 'LPAREN') {
                throw new SyntaxError('Unexpected character');
            }
            tokens.push({ kind: 'MINUS', value: '-' });
            i++;
            continue;
        }

        // Number parsing
        let numStr = '';
        while (i < len && /[0-9.]/.test(expression[i])) {
            numStr += expression[i];
            i++;
        }

        if (numStr) {
            const val = parseFloat(numStr);
            if (isNaN(val)) {
                throw new SyntaxError('Invalid number');
            }
            tokens.push({ kind: 'NUMBER', value: numStr });
            continue;
        }

        throw new SyntaxError(`Unexpected character: ${char}`);
    }

    return tokens;
}
