export function formatBytes(bytes, decimals = 1) {
    // Validate bytes: must be a finite number
    if (!Number.isFinite(bytes)) {
        throw new TypeError('bytes must be a finite number');
    }

    // Validate decimals: must be an integer between 0 and 10 inclusive
    if (!Number.isInteger(decimals) || decimals < 0 || decimals > 10) {
        throw new RangeError('decimals must be an integer from 0 to 10');
    }

    const units = ['B', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB'];
    const factor = 1024;

    // Handle negative numbers by working with absolute value
    const absBytes = Math.abs(bytes);

    // Find the appropriate unit
    for (let i = 0; i < units.length; i++) {
        if (absBytes < factor) {
            break;
        }
        absBytes /= factor;
    }

    let formattedValue;

    // If value is less than 1 in the current unit, format as integer bytes
    if (absBytes < 1) {
        formattedValue = Math.round(absBytes);
    } else {
        // Format with specified decimals
        const roundedValue = parseFloat(absBytes.toFixed(decimals));

        // Check if rounding resulted in exactly 1024 of the current unit
        // In that case, move to the next unit (e.g., 1024.0 KiB -> 1.0 MiB)
        if (roundedValue === 1024 && decimals >= 1) {
            absBytes = roundedValue / factor;
            formattedValue = parseFloat(absBytes.toFixed(decimals));
        } else {
            formattedValue = roundedValue;
        }
    }

    return `${formattedValue} ${units[i]}`;
}
