// matchWildcard.js
/**
 * Matches text against a wildcard pattern where:
 * - '?' matches exactly one character
 * - '*' matches any sequence of characters (including empty)
 * - Other characters must match exactly
 * 
 * Uses an efficient two-pointer approach with backtracking for '*' to handle
 * adversarial inputs efficiently without building RegExp objects.
 */
export function matchWildcard(pattern, text) {
  const pLen = pattern.length;
  const tLen = text.length;

  // Edge cases: empty pattern matches empty text, otherwise false
  if (pLen === 0) return tLen === 0;
  if (tLen === 0) return pattern.endsWith('*');

  let pIdx = 0;
  let tIdx = 0;

  while (pIdx < pLen || tIdx < tLen) {
    // If both pointers are at the end, we've matched completely
    if (pIdx === pLen && tIdx === tLen) {
      return true;
    }

    // If pattern pointer is at end but text isn't, no match possible
    if (pIdx === pLen) {
      return false;
    }

    // Handle '*' - greedy matching with backtracking
    if (pattern[pIdx] === '*') {
      let starStart = pIdx;
      while (starStart > 0 && pattern[starStart - 1] === '*') {
        starStart--;
      }

      // Try to match '*' against text starting from tIdx
      // We need to find the longest prefix of text that matches, then backtrack if needed
      let maxMatch = tLen - tIdx;

      // Greedily consume text with '*'
      while (tIdx < tLen && pattern[pIdx + 1] !== '*') {
        pIdx++;
        tIdx++;
      }

      // If we consumed all text, check if remaining pattern matches empty string
      if (tIdx === tLen) {
        return matchWildcard(pattern.slice(pIdx), '');
      }

      // Backtrack: try shorter matches for '*'
      while (tIdx > starStart) {
        tIdx--;
        pIdx = starStart + 1;
        if (matchWildcard(pattern, text)) {
          return true;
        }
      }

      continue;
    }

    // Normal character matching
    if (pattern[pIdx] === '?' || pattern[pIdx] === text[tIdx]) {
      pIdx++;
      tIdx++;
    } else {
      // Mismatch - backtrack only if we have a '*' before current position
      let backPtr = pIdx;
      while (backPtr > 0 && pattern[backPtr - 1] !== '*') {
        backPtr--;
      }

      if (backPtr === 0) {
        return false; // No '*' to backtrack over
      }

      // Backtrack: try matching '*' with fewer characters
      pIdx = backPtr + 1;
      tIdx--;
    }
  }

  return false;
}
